// Onecloseddegree6Qcomponent overQQ[e]/f6; certifiedunitpivots only, no GB/points.
#include <flint/fmpq.h>
#include <flint/fmpq_poly.h>
#include <flint/fmpq_mpoly.h>
#include <algorithm>
#include <array>
#include <cassert>
#include <chrono>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>
using namespace std;chrono::steady_clock::time_point start;fmpq_mpoly_ctx_t ctx;
void tick(){assert(chrono::duration<double>(chrono::steady_clock::now()-start).count()<50);}
struct E{fmpq_poly_t p;E(){fmpq_poly_init(p);}E(const E&x):E(){fmpq_poly_set(p,x.p);}E(E&&x):E(){fmpq_poly_swap(p,x.p);}E&operator=(E x){fmpq_poly_swap(p,x.p);return*this;}~E(){fmpq_poly_clear(p);}};
E field_mod;vector<E>inv_elements,inv_values,inv_bez_mod,inv_bez_element;
E eo(){E p;fmpq_poly_one(p.p);return p;}bool zero(const E&p){return fmpq_poly_is_zero(p.p);}bool eq(const E&a,const E&b){return fmpq_poly_equal(a.p,b.p);}E er(const E&a){E p;fmpq_poly_rem(p.p,a.p,field_mod.p);return p;}E add(const E&a,const E&b){E p;fmpq_poly_add(p.p,a.p,b.p);return p;}E neg(const E&a){E p;fmpq_poly_neg(p.p,a.p);return p;}E mul(const E&a,const E&b){E p;fmpq_poly_mul(p.p,a.p,b.p);tick();return er(p);}E scale(const E&a,const fmpq_t c){E p;fmpq_poly_scalar_mul_fmpq(p.p,a.p,c);return p;}
E inverse(const E&a){assert(!zero(a));E g,s,t,x,y;fmpq_poly_xgcd(g.p,s.p,t.p,field_mod.p,a.p);if(!fmpq_poly_is_one(g.p)){cerr<<"NONUNIT_FIELD_PIVOT_STOP\n";abort();}fmpq_poly_mul(x.p,s.p,field_mod.p);fmpq_poly_mul(y.p,t.p,a.p);assert(eq(add(x,y),eo()));E r=er(t);assert(eq(mul(a,r),eo()));inv_elements.push_back(a);inv_values.push_back(r);inv_bez_mod.push_back(s);inv_bez_element.push_back(t);return r;}
struct P{fmpq_mpoly_t p;P(){fmpq_mpoly_init(p,ctx);}P(const P&x):P(){fmpq_mpoly_set(p,x.p,ctx);}P(P&&x):P(){fmpq_mpoly_swap(p,x.p,ctx);}~P(){fmpq_mpoly_clear(p,ctx);}};
void readE(istream&f,E&p){long n;f>>n;fmpq_t c;fmpq_init(c);for(long i=0;i<n;i++){long j;string s;f>>j>>s;assert(!fmpq_set_str(c,s.c_str(),10));fmpq_canonicalise(c);fmpq_poly_set_coeff_fmpq(p.p,j,c);}fmpq_clear(c);}
void readP(istream&f,P&p){long n;f>>n;fmpq_t c;fmpq_init(c);ulong x[3];for(long i=0;i<n;i++){string s;f>>s>>x[0]>>x[1]>>x[2];assert(!fmpq_set_str(c,s.c_str(),10));fmpq_canonicalise(c);fmpq_mpoly_push_term_fmpq_ui(p.p,c,x,ctx);}fmpq_mpoly_sort_terms(p.p,ctx);fmpq_mpoly_combine_like_terms(p.p,ctx);assert(fmpq_mpoly_is_canonical(p.p,ctx));fmpq_clear(c);}
void je(ostream&o,const E&p){o<<'[';fmpq_t c;fmpq_init(c);bool first=true;for(long i=fmpq_poly_degree(p.p);i>=0;i--){fmpq_poly_get_coeff_fmpq(c,p.p,i);if(fmpq_is_zero(c))continue;if(!first)o<<',';first=false;char*s=fmpq_get_str(nullptr,10,c);o<<'['<<i<<",\""<<s<<"\"]";flint_free(s);}o<<']';fmpq_clear(c);assert(o.tellp()<30*1024*1024);}
using B=array<E,2>;E q0,q1;
B bo(){B p;p[0]=eo();return p;}B ba(const B&a,const B&b){return {add(a[0],b[0]),add(a[1],b[1])};}B bn(const B&a){return {neg(a[0]),neg(a[1])};}B bs(const B&a,const E&s){return {mul(a[0],s),mul(a[1],s)};}B bm(const B&a,const B&b){E vv=mul(a[1],b[1]);return {add(mul(a[0],b[0]),neg(mul(q0,vv))),add(add(mul(a[0],b[1]),mul(a[1],b[0])),neg(mul(q1,vv)))};}bool beq(const B&a,const B&b){return eq(a[0],b[0])&&eq(a[1],b[1]);}
using A=array<B,4>;array<B,4>h;
A ao(){A a;a[0]=bo();return a;}A aa(const A&a,const A&b){A p;for(int i=0;i<4;i++)p[i]=ba(a[i],b[i]);return p;}A am(const A&a,const A&b){array<B,7>v;for(int i=0;i<4;i++)for(int j=0;j<4;j++)v[i+j]=ba(v[i+j],bm(a[i],b[j]));for(int j=6;j>=4;j--){B t=v[j];for(int i=0;i<4;i++)v[j-4+i]=ba(v[j-4+i],bn(bm(t,h[i])));v[j]=B();}A r;for(int i=0;i<4;i++)r[i]=v[i];return r;}A ab(const A&a,const B&s){A r;for(int i=0;i<4;i++)r[i]=bm(a[i],s);return r;}bool aeq(const A&a,const A&b){for(int i=0;i<4;i++)if(!beq(a[i],b[i]))return false;return true;}A apow(A p,long n){A r=ao();while(n){if(n&1)r=am(r,p);n>>=1;if(n)p=am(p,p);}return r;}
vector<B>ap;vector<E>ep;vector<A>dp;
E eval_pure_e(const P&p,int a_degree){E r;fmpq_t c;fmpq_init(c);ulong x[3];for(long i=0;i<fmpq_mpoly_length(p.p,ctx);i++){fmpq_mpoly_get_term_exp_ui(x,p.p,i,ctx);if(x[0]!=(ulong)a_degree)continue;assert(x[2]==0);fmpq_mpoly_get_term_coeff_fmpq(c,p.p,i,ctx);r=add(r,scale(ep.at(x[1]),c));}fmpq_clear(c);return r;}
B hcoef(const P&p,int d){B r;fmpq_t c;fmpq_init(c);ulong x[3];for(long i=0;i<fmpq_mpoly_length(p.p,ctx);i++){fmpq_mpoly_get_term_exp_ui(x,p.p,i,ctx);if(x[2]!=(ulong)d)continue;fmpq_mpoly_get_term_coeff_fmpq(c,p.p,i,ctx);r=ba(r,bs(ap.at(x[0]),scale(ep.at(x[1]),c)));}fmpq_clear(c);return r;}
A evaluate(const P&p){A r;fmpq_t c;fmpq_init(c);ulong x[3];for(long i=0;i<fmpq_mpoly_length(p.p,ctx);i++){fmpq_mpoly_get_term_exp_ui(x,p.p,i,ctx);fmpq_mpoly_get_term_coeff_fmpq(c,p.p,i,ctx);r=aa(r,ab(dp.at(x[2]),bs(ap.at(x[0]),scale(ep.at(x[1]),c))));}fmpq_clear(c);return r;}
A basis(int b){A r;r[b/2][b%2]=eo();return r;}vector<E>vec(const A&a){vector<E>v(8);for(int j=0;j<4;j++)for(int k=0;k<2;k++)v[2*j+k]=a[j][k];return v;}A avec(const vector<E>&v,int start=0){A a;for(int j=0;j<4;j++)for(int k=0;k<2;k++)a[j][k]=v[start+2*j+k];return a;}
void jb(ostream&o,const B&b){o<<'[';je(o,b[0]);o<<',';je(o,b[1]);o<<']';}void ja(ostream&o,const A&a){o<<'[';for(int j=0;j<4;j++){if(j)o<<',';jb(o,a[j]);}o<<']';}void jm(ostream&o,const vector<vector<E>>&M){o<<'[';for(int i=0;i<(int)M.size();i++){if(i)o<<',';o<<'[';for(int j=0;j<(int)M[i].size();j++){if(j)o<<',';je(o,M[i][j]);}o<<']';}o<<']';}
int main(int argc,char**argv){assert(argc==3);start=chrono::steady_clock::now();fmpq_mpoly_ctx_init(ctx,3,ORD_LEX);{
 ifstream f(argv[1]);readE(f,field_mod);assert(fmpq_poly_degree(field_mod.p)==6);P Q,Hclear,U;readP(f,Q);readP(f,Hclear);readP(f,U);int ns;f>>ns;assert(ns==22);vector<P>source(ns);for(auto&p:source)readP(f,p);string extra;assert(!(f>>extra));E eg;fmpq_poly_set_coeff_si(eg.p,1,1);ep.push_back(eo());for(int i=1;i<=20;i++)ep.push_back(mul(ep.back(),eg));q0=eval_pure_e(Q,0);q1=eval_pure_e(Q,1);assert(!zero(q0));E iq0=inverse(q0);B ag;ag[1]=eo();B ainv={neg(mul(q1,iq0)),neg(iq0)};assert(beq(bm(ag,ainv),bo()));ap.push_back(bo());for(int i=1;i<=20;i++)ap.push_back(bm(ap.back(),ag));B inv5=bo();for(int i=0;i<5;i++)inv5=bm(inv5,ainv);array<B,5>hc,hh;for(int i=0;i<5;i++){hc[i]=hcoef(Hclear,i);hh[i]=bm(hc[i],inv5);}assert(beq(hh[4],bo()));for(int i=0;i<4;i++)h[i]=hh[i];dp.push_back(ao());A dg;dg[1]=bo();for(int i=1;i<=20;i++)dp.push_back(am(dp.back(),dg));vector<A>images;for(auto&p:source)images.push_back(evaluate(p));A ui=evaluate(U),target=apow(ui,8);
 vector<vector<E>>M(8,vector<E>(176));vector<E>T=vec(target);for(int i=0;i<22;i++)for(int b=0;b<8;b++){auto v=vec(am(images[i],basis(b)));for(int row=0;row<8;row++)M[row][i*8+b]=v[row];}long coeffcount=0,maxbits=0;fmpq_t cv;fmpq_init(cv);for(auto&row:M)for(auto&p:row){for(long k=0;k<=fmpq_poly_degree(p.p);k++){fmpq_poly_get_coeff_fmpq(cv,p.p,k);if(fmpq_is_zero(cv))continue;coeffcount++;maxbits=max(maxbits,(long)(fmpz_bits(fmpq_numref(cv))+fmpz_bits(fmpq_denref(cv))));}}fmpq_clear(cv);assert(coeffcount<150000);assert(coeffcount*(150+maxbits*31/100)<8*1024*1024);cerr<<"MODEL_PREFLIGHT_PASS fieldcoeffs="<<coeffcount<<" bits="<<maxbits<<"\n";
 {ofstream ck(string(argv[2])+".model-checkpoint.json");ck<<"{\"matrix_M\":";jm(ck,M);ck<<",\"target\":[";for(int i=0;i<8;i++){if(i)ck<<',';je(ck,T[i]);}ck<<"]}\n";}
 vector<vector<E>>C=M,R(8,vector<E>(8));for(int i=0;i<8;i++){C[i].push_back(T[i]);R[i][i]=eo();}vector<int>pivots;int rank=0;
 for(int col=0;col<176&&rank<8;col++){int pr=rank;while(pr<8&&zero(C[pr][col]))pr++;if(pr==8)continue;swap(C[pr],C[rank]);swap(R[pr],R[rank]);E iv=inverse(C[rank][col]);for(int j=0;j<=176;j++)C[rank][j]=mul(C[rank][j],iv);for(int j=0;j<8;j++)R[rank][j]=mul(R[rank][j],iv);for(int i=0;i<8;i++)if(i!=rank&&!zero(C[i][col])){E cf=C[i][col];for(int j=0;j<=176;j++)C[i][j]=add(C[i][j],neg(mul(cf,C[rank][j])));for(int j=0;j<8;j++)R[i][j]=add(R[i][j],neg(mul(cf,R[rank][j])));}pivots.push_back(col);rank++;}
 bool solved=true;int obstruct=-1;for(int i=rank;i<8;i++)if(!zero(C[i][176])){solved=false;obstruct=i;}vector<E>X(176);if(solved)for(int i=0;i<rank;i++)X[pivots[i]]=C[i][176];vector<A>cofs;if(solved){A dot;for(int i=0;i<22;i++){cofs.push_back(avec(X,i*8));dot=aa(dot,am(cofs.back(),images[i]));}assert(aeq(dot,target));}for(int i=0;i<8;i++)for(int j=0;j<=176;j++){E z;for(int k=0;k<8;k++)z=add(z,mul(R[i][k],j==176?T[k]:M[k][j]));assert(eq(z,C[i][j]));}cerr<<"FIELD_MEMBERSHIP_PASS solved="<<solved<<" rank="<<rank<<"\n";
 ofstream o(argv[2]);o<<"{\"q0_reduced\":";je(o,q0);o<<",\"q1_reduced\":";je(o,q1);o<<",\"a_inverse\":";jb(o,ainv);o<<",\"Hclear_coefficients\":[";for(int i=0;i<5;i++){if(i)o<<',';jb(o,hc[i]);}o<<"],\"H_monic_coefficients\":[";for(int i=0;i<5;i++){if(i)o<<',';jb(o,hh[i]);}o<<"],\"all22_original_source_images\":[";for(int i=0;i<22;i++){if(i)o<<',';ja(o,images[i]);}o<<"],\"U_image\":";ja(o,ui);o<<",\"target_U_power8\":";ja(o,target);o<<",\"matrix_M\":";jm(o,M);o<<",\"rref_augmented\":";jm(o,C);o<<",\"row_transformation_R\":";jm(o,R);o<<",\"pivot_columns\":[";for(int i=0;i<rank;i++){if(i)o<<',';o<<pivots[i];}o<<"],\"all_field_inverse_certificates\":[";for(int i=0;i<(int)inv_elements.size();i++){if(i)o<<',';o<<"{\"element\":";je(o,inv_elements[i]);o<<",\"inverse\":";je(o,inv_values[i]);o<<",\"Bezout_modulus\":";je(o,inv_bez_mod[i]);o<<",\"Bezout_element\":";je(o,inv_bez_element[i]);o<<'}';}o<<"],\"membership_solved\":"<<(solved?"true":"false")<<",\"source22_cofactor_witness\":[";for(int i=0;i<(int)cofs.size();i++){if(i)o<<',';ja(o,cofs[i]);}o<<"],\"nonmembership_obstruction_row\":"<<obstruct<<",\"rank\":"<<rank<<",\"matrix_rational_coefficient_count\":"<<coeffcount<<",\"matrix_max_numerator_plus_denominator_bits\":"<<maxbits<<",\"native_seconds\":"<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<"}\n";
}ap.clear();ep.clear();dp.clear();for(auto&x:h)x=B();inv_elements.clear();inv_values.clear();inv_bez_mod.clear();inv_bez_element.clear();q0=E();q1=E();field_mod=E();fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
